const axios = require('axios');

async function getInstagramReel(url) {
  try {
    const response = await axios.get('https://igexport.com/api/ig-reels/', {
      params: {
        url: url
      }
    });

    if (response.data && response.data.ok) {
      return response.data.media.videoUrl;
    } else {
      return 'Gagal mendapatkan video reel.';
    }
  } catch (error) {
    console.error('Terjadi kesalahan:', error);
    return 'Terjadi kesalahan saat memproses permintaan.';
  }
}

const reelUrl = 'https://www.instagram.com/reel/DaLRcG5pWQo/?igsh=eTNtbnFsdDFuaDd4';
